input.command:
python -c 'import torch; from model.utils import artanh; import train_rqvae as t; x=torch.tensor([1.0],dtype=torch.float32,requires_grad=True); y=artanh(x); assert torch.isfinite(y).all(); y.sum().backward(); assert torch.isfinite(x.grad).all(); print("artanh_float32", y.item(), "grad", x.grad.item()); s=torch.tensor([[0.2,0.1],[0.0,0.3]],requires_grad=True); c=torch.tensor([[0.1,0.2],[0.2,0.1]],requires_grad=True); results={};
for name,b_on,g_on in (("both_on",True,True),("behaviour_off",False,True),("euclidean",True,False)):
 t.BEHAVIOUR_ON=b_on; loss=t._residual_contrast(s,c,geometry_on=g_on); loss.backward(retain_graph=True); grad=s.grad.detach().clone(); s.grad.zero_(); c.grad.zero_(); assert torch.isfinite(loss) and torch.isfinite(grad).all(); results[name]=(round(loss.item(),8),bool(torch.isfinite(grad).all())); print(name,"loss",loss.item(),"encoder_grad_finite",bool(torch.isfinite(grad).all()),"grad_norm",grad.norm().item())
print("geometry_callsite_explicit", "geometry_on=GEOMETRY_ON" in open("train_rqvae.py").read()); print("single_gpu_branch", "SINGLE_GPU_ENV = \"GENREC_SINGLE_GPU\"" in open("train_rqvae.py").read()); print("artifact_path_rooted", "RESULT_DIR = REPO_ROOT / \"results\" / \"stage2_RQ-VAE\" / ARM_NAME" in open("train_rqvae.py").read())'

